73	// It only draws and reports clicks; the row owns what a cell does.
74	class ColourCell : public wxPanel
75	{
76	public:
77	    ColourCell(wxWindow* parent, const ShellTheme& theme, const ShellPalette& palette, const wxColour& colour,
78	               bool current, std::function<void()> clicked)
79	        : wxPanel(parent, wxID_ANY, wxDefaultPosition,
80	                  parent->FromDIP(wxSize(theme.metrics().swatch.size, theme.metrics().swatch.size)))
81	        , m_swatch(theme.metrics().swatch), m_palette(palette), m_colour(colour), m_current(current)
82	        , m_clicked(std::move(clicked))
83	    {
84	        SetBackgroundStyle(wxBG_STYLE_PAINT);
85	        SetCursor(wxCursor(wxCURSOR_HAND));
86	        Bind(wxEVT_PAINT, &ColourCell::paint, this);
87	        Bind(wxEVT_ENTER_WINDOW, [this](wxMouseEvent&) { m_hover = true; Refresh(); });
88	        Bind(wxEVT_LEAVE_WINDOW, [this](wxMouseEvent&) { m_hover = false; Refresh(); });
89	        Bind(wxEVT_LEFT_UP, [this](wxMouseEvent&) { if (m_clicked) m_clicked(); });
90	    }
91	
92	private:
93	    void paint(wxPaintEvent&)
94	    {
95	        wxAutoBufferedPaintDC dc(this);
96	        dc.SetBackground(wxBrush(m_palette.surface_raised));
97	        dc.Clear();
98	        std::unique_ptr<wxGraphicsContext> gc(wxGraphicsContext::Create(dc));
99	        if (!gc) return;
100	        const wxRect box    = GetClientRect().Deflate(FromDIP(m_current ? m_swatch.current_inset : m_swatch.inset));
101	        const double radius = FromDIP(m_swatch.radius);
102	        if (!m_colour.IsOk()) {
103	            // The "+": the system picker, for a colour not saved yet.
104	            gc->SetPen(wxPen(m_hover ? m_palette.border_strong : m_palette.border_subtle, FromDIP(m_swatch.ring_width)));
105	            gc->SetBrush(*wxTRANSPARENT_BRUSH);
106	            gc->DrawRoundedRectangle(box.x + 0.5, box.y + 0.5, box.width - 1, box.height - 1, radius);
107	            gc->SetPen(wxPen(m_palette.text_secondary, FromDIP(m_swatch.glyph_width)));
108	            const double cx = box.x + box.width / 2., cy = box.y + box.height / 2., arm = box.width / 4.;
109	            gc->StrokeLine(cx - arm, cy, cx + arm, cy);
110	            gc->StrokeLine(cx, cy - arm, cx, cy + arm);
111	            return;
112	        }
113	        // The current colour is ringed; the others show a quiet edge so a
114	        // white or near-background colour stays visible.
115	        gc->SetPen(wxPen(m_current || m_hover ? m_palette.border_strong : m_palette.border_subtle,
116	                         FromDIP(m_current ? m_swatch.current_ring_width : m_swatch.ring_width)));
117	        gc->SetBrush(wxBrush(m_colour));
118	        gc->DrawRoundedRectangle(box.x + 0.5, box.y + 0.5, box.width - 1, box.height - 1, radius);
119	    }
120	
121	    SwatchMetrics         m_swatch;
122	    ShellPalette          m_palette;
123	    wxColour              m_colour;
124	    bool                  m_current{false};
125	    bool                  m_hover{false};
126	    std::function<void()> m_clicked;
127	};
128	
129	// The colour row: its caption, then the grid of cells. It is one stop in the
130	// menu's keyboard model: Left and Right move between cells, Return and Space
131	// apply one, and the cell the keyboard is on carries the focus ring, drawn in
132	// the gap around it so the swatch itself never changes size.
133	class ColourRow : public wxPanel, public HeaderMenuKeyView
134	{
135	public:
136	    struct Cell
137	    {
138	        wxColour              colour; // invalid for the "+"
139	        bool                  current{false};
140	        std::function<void()> apply;
141	    };
142	
143	    ColourRow(wxWindow* parent, const ShellTheme& theme, const ShellPalette& palette, std::vector<Cell> cells,
144	              const std::string& cursor, std::function<void(const std::string&)> cursor_moved)
145	        : wxPanel(parent)
146	        , m_palette(palette), m_swatch(theme.metrics().swatch), m_ring(theme.metrics().focus.width)
147	        , m_cursor_moved(std::move(cursor_moved))
148	    {
149	        SetBackgroundStyle(wxBG_STYLE_PAINT);
150	        Bind(wxEVT_PAINT, &ColourRow::paint, this);
151	        auto* column = new wxBoxSizer(wxVERTICAL);
152	
153	        auto* caption = new wxStaticText(this, wxID_ANY, _L("COLOUR"));
154	        style_label(*caption, theme, TextRole::Metadata, palette.text_secondary);
155	        caption->SetBackgroundColour(palette.surface_raised);
156	        // The caption lines up with the cells, which stand in by the ring's
157	        // width so a ring round an outer cell is not cut off.
158	        column->Add(caption, 0, wxLEFT | wxBOTTOM, FromDIP(m_ring));
159	        column->AddSpacer(FromDIP(m_swatch.caption_gap) - FromDIP(m_ring));
160	
161	        auto* grid = new wxGridSizer(int(kColoursPerRow), FromDIP(m_swatch.gap), FromDIP(m_swatch.gap));
162	        for (std::size_t index = 0; index < cells.size(); ++index) {
163	            auto* cell = new ColourCell(this, theme, palette, cells[index].colour, cells[index].current,
164	                                        [this, index] { activate(index); });
165	            const std::string key = colour_key(cells[index].colour);
166	            cell->SetName(key == kPickerKey ? wxString("Other colour") : wxString::FromUTF8(key));
167	            cell->SetToolTip(key == kPickerKey ? _L("Other colour…") : wxString::FromUTF8(key));
168	            grid->Add(cell, 0);
169	            m_cells.push_back(cell);
170	            m_keys.push_back(key);
171	            m_apply.push_back(std::move(cells[index].apply));
172	        }
173	        column->Add(grid, 0, wxLEFT | wxRIGHT | wxBOTTOM, FromDIP(m_ring));
174	        SetSizerAndFit(column);
175	
176	        const auto found = std::find(m_keys.begin(), m_keys.end(), cursor);
177	        m_cursor         = found == m_keys.end() ? 0 : std::size_t(found - m_keys.begin());
178	    }
179	
180	    void set_key_focus(bool focused) override
181	    {
182	        m_focused = focused;
183	        if (focused) report_cursor();
184	        Refresh();
185	    }
186	
187	    bool on_menu_key(int key_code) override
188	    {
189	        if (m_cells.empty()) return false;
190	        switch (key_code) {
191	        case WXK_LEFT:
192	            if (m_cursor > 0) --m_cursor;
193	            report_cursor();
194	            Refresh();
195	            return true;
196	        case WXK_RIGHT:
197	            if (m_cursor + 1 < m_cells.size()) ++m_cursor;
198	            report_cursor();
199	            Refresh();
200	            return true;
201	        case WXK_RETURN:
202	        case WXK_NUMPAD_ENTER:
203	        case WXK_SPACE:
204	            activate(m_cursor);
205	            return true;
206	        default: return false;
207	        }
208	    }
209	
210	    wxWindow* key_child() const override { return m_cells.empty() ? nullptr : m_cells[m_cursor]; }
211	
212	private:
213	    void report_cursor()
214	    {
215	        if (m_cursor_moved && m_cursor < m_keys.size()) m_cursor_moved(m_keys[m_cursor]);
216	    }
217	
218	    // Applying a colour rebuilds the menu, which destroys this row and the
219	    // cell that asked. The menu runs it once the current event is done.
220	    void activate(std::size_t index)
221	    {
222	        if (index >= m_apply.size()) return;
223	        m_cursor = index;
224	        report_cursor();
225	        auto apply = m_apply[index];
226	        wxWindow* menu = GetParent();
227	        menu->CallAfter([alive = wxWeakRef<wxWindow>(menu), apply] { if (alive && apply) apply(); });
228	    }
229	
230	    void paint(wxPaintEvent&)
231	    {
232	        wxAutoBufferedPaintDC dc(this);
233	        dc.SetBackground(wxBrush(m_palette.surface_raised));
234	        dc.Clear();
235	        if (!m_focused || m_cursor >= m_cells.size()) return;
236	        std::unique_ptr<wxGraphicsContext> gc(wxGraphicsContext::Create(dc));
237	        if (!gc) return;
238	        // The ring sits wholly outside the cell, in the gap the grid leaves.
239	        const double ring = FromDIP(m_ring);
240	        const wxRect cell = m_cells[m_cursor]->GetRect();
241	        gc->SetPen(wxPen(m_palette.border_focus, ring));
242	        gc->SetBrush(*wxTRANSPARENT_BRUSH);
243	        gc->DrawRoundedRectangle(cell.x - ring / 2., cell.y - ring / 2., cell.width + ring, cell.height + ring,
244	                                 FromDIP(m_swatch.radius) + ring / 2.);
245	    }
246	
247	    ShellPalette                             m_palette;
248	    SwatchMetrics                            m_swatch;
249	    int                                      m_ring{0};
250	    std::function<void(const std::string&)> m_cursor_moved;
251	    std::vector<ColourCell*>                 m_cells;
252	    std::vector<std::string>                 m_keys;
253	    std::vector<std::function<void()>>       m_apply;
254	    std::size_t                              m_cursor{0};
255	    bool                                     m_focused{false};
256	};
