264	void FilamentMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Host host, HeaderButton& anchor)
265	{
266	    auto self      = std::make_shared<FilamentMenu>(owner, theme, dark, std::move(host));
267	    self->m_anchor = &anchor;
268	    reopen(self, View{});
269	}
