271	void FilamentMenu::reopen(const Ptr& self, View view)
272	{
273	    self->m_stepping_out = false;
274	    if (!self->m_anchor) {
275	        // The menu cannot come back, so the visit ends here and its line is
276	        // not lost.
277	        end_visit(self);
278	        return;
279	    }
280	    auto* menu   = new HeaderMenu(self->m_owner, self->m_theme, self->m_dark, {});
281	    self->m_menu = menu;
282	    // A visit ends when the person leaves the menu: click-away, Esc, Tab, or a
283	    // row that hands off for good (Filament settings…, the tray row). A close
284	    // the menu makes itself, to put a dialog up and come back, is not one.
285	    // The callbacks hold the controller, so it is still alive here.
286	    menu->set_dismiss_listener([self] {
287	        if (self->m_stepping_out) return;
288	        self->m_owner->CallAfter([self] { end_visit(self); });
289	    });
290	    show(self, view);
291	    menu->open(*self->m_anchor);
292	}
293	
294	void FilamentMenu::step_out(const Ptr& self, View back, const std::function<void()>& task)
295	{
296	    // The dialogs this puts up are modal, and on macOS a system panel's window
297	    // frame is its only way out -- a transient popup above it would cover
298	    // that frame. The popup goes first and comes back afterwards, in the same
299	    // visit.
300	    self->m_stepping_out = true;
301	    if (auto* menu = self->m_menu.get()) menu->close();
302	    task();
303	    reopen(self, back);
304	}
