314	void FilamentMenu::show(const Ptr& self, View view)
315	{
316	    const auto slots = SetupCommands::filament_slots();
317	    if (view.slot && *view.slot < slots.size())
318	        show_slot(self, *view.slot, view.from_list);
319	    else if (slots.size() > 1)
320	        show_slots(self);
321	    else
322	        show_slot(self, 0, false);
