325	void FilamentMenu::add_tray_row(const Ptr& self, std::vector<HeaderMenuItem>& rows)
326	{
327	    const SetupCommands::TrayState trays = SetupCommands::printer_trays();
328	    if (trays == SetupCommands::TrayState::None)
329	        return; // no trays reported: no row at all
330	    HeaderMenuItem row;
331	    row.label = _L("Use what's loaded on the printer…");
332	    if (trays == SetupCommands::TrayState::Offline) {
333	        // Kept in place, greyed, with the reason, so the menu does not jump
334	        // when the printer comes back.
335	        row.enabled              = false;
336	        row.decoration.sub_label = wxString::Format(_L("%s is offline. Turn it on to read what's loaded."),
337	                                                    SetupCommands::current_printer().nickname);
338	    } else {
339	        // On request only: Orca's own sync, unchanged. It hands off for good,
340	        // so the menu closes and the visit ends.
341	        row.invoke = [self] {
342	            if (self->m_host.plater && SetupCommands::sync_from_printer(*self->m_host.plater) && self->m_host.changed)
343	                self->m_host.changed();
344	        };
345	    }
346	    rows.push_back(std::move(row));
347	    rows.push_back(separator());
348	}
