350	void FilamentMenu::show_slots(const Ptr& self)
351	{
352	    auto* menu = self->m_menu.get();
353	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
354	    menu->set_header_builder(nullptr);
355	    const auto printer = SetupCommands::current_printer();
356	    const auto slots   = SetupCommands::filament_slots();
357	
358	    std::vector<HeaderMenuItem> rows;
359	    add_tray_row(self, rows);
360	    rows.push_back(title_row(wxString::Format(_L("FILAMENTS ON %s"), printer_caption(printer, shared_nozzle(printer)))));
361	    for (const auto& slot : slots) {
362	        HeaderMenuItem row;
363	        // Number, dot, name, as the design reads. The number is drawn ahead
364	        // of the dot; the row's name still says all three in words.
365	        row.label           = slot.filament.alias;
366	        row.name            = wxString::Format("%d  %s", int(slot.index + 1), slot.filament.alias);
367	        row.decoration.lead = wxString::Format("%d", int(slot.index + 1));
368	        row.decoration.dot  = wxColour(slot.colour);
369	        wxString detail;
370	        if (slot.nozzle > 0.)
371	            detail = nozzle_text(slot.nozzle);
372	        if (slot.used)
373	            detail += (detail.empty() ? wxString() : middot()) + _L("on plate");
374	        row.decoration.detail   = detail;
375	        row.decoration.trailing = HeaderIcon::Right;
376	        row.keeps_open          = true;
377	        row.invoke              = [self, index = slot.index] { show_slot(self, index, true); };
378	        rows.push_back(std::move(row));
379	    }
380	
381	    HeaderMenuItem add;
382	    add.separator  = true;
383	    add.label      = _L("Add a slot");
384	    add.keeps_open = true;
385	    add.invoke     = [self] {
386	        if (!self->m_host.plater) return;
387	        const auto added = SetupCommands::add_filament_slot(*self->m_host.plater);
388	        if (self->m_host.changed) self->m_host.changed();
389	        show(self, View{added, true});
390	    };
391	    rows.push_back(std::move(add));
392	    menu->replace_items(std::move(rows));
393	}
