395	void FilamentMenu::show_slot(const Ptr& self, std::size_t slot, bool from_list)
396	{
397	    auto* menu = self->m_menu.get();
398	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
399	    const auto printer = SetupCommands::current_printer();
400	    const auto slots   = SetupCommands::filament_slots();
401	    if (slot >= slots.size()) { show_slots(self); return; }
402	    const auto& current = slots[slot];
403	    const View  here{slot, from_list};
404	
405	    std::vector<HeaderMenuItem> rows;
406	    if (from_list) {
407	        // The title is also the way back to the slot list.
408	        HeaderMenuItem back;
409	        back.label      = wxString::Format(_L("FILAMENT · SLOT %d · %s"), int(slot + 1),
410	                                           printer_caption(printer, current.nozzle > 0. ? current.nozzle : printer.nozzle));
411	        back.icon       = HeaderIcon::Back;
412	        back.keeps_open = true;
413	        back.invoke     = [self] { show_slots(self); };
414	        rows.push_back(std::move(back));
415	    } else {
416	        add_tray_row(self, rows);
417	        rows.push_back(title_row(wxString::Format(_L("FILAMENT ON %s"), printer_caption(printer, printer.nozzle))));
418	    }
419	    // The colour row sits directly under the title: colour is the most
420	    // frequent change. The popup counts rows it places, and a bare separator
421	    // is not one.
422	    const int colour_after = int(std::count_if(rows.begin(), rows.end(),
423	                                               [](const HeaderMenuItem& row) { return !(row.title && row.label.empty()); }));
424	    menu->set_header_builder([self, here](wxWindow* parent) { return build_colour_row(self, parent, here); }, colour_after);
425	
426	    rows.push_back(title_row(_L("INSTALLED")));
427	    for (const auto& filament : SetupCommands::compatible_filaments()) {
428	        HeaderMenuItem row;
429	        row.label            = filament.alias;
430	        row.decoration.check = filament.preset_name == current.filament.preset_name;
431	        // Stays open: a colour click after this is the same visit.
432	        row.keeps_open = true;
433	        row.invoke     = [self, slot, from_list, preset = filament.preset_name] {
434	            if (!self->m_host.plater) return;
435	            if (SetupCommands::select_filament_preset(*self->m_host.plater, slot, preset)) {
436	                self->m_visit.filaments[slot] = preset;
437	                if (self->m_host.changed) self->m_host.changed();
438	            }
439	            show_slot(self, slot, from_list);
440	        };
441	        rows.push_back(std::move(row));
442	    }
443	
444	    // Everything that fits, installed or not, is Orca's own page; it installs
445	    // what is ticked there, and the menu comes back with the list current,
446	    // in the same visit.
447	    HeaderMenuItem other;
448	    other.separator           = true;
449	    other.label               = _L("Other filament…");
450	    other.decoration.trailing = HeaderIcon::Right;
451	    other.keeps_open          = true;
452	    other.invoke              = [self, here] {
453	        step_out(self, here, [self] {
454	            SetupCommands::open_filament_library();
455	            if (self->m_host.changed) self->m_host.changed();
456	        });
457	    };
458	    rows.push_back(std::move(other));
459	
460	    HeaderMenuItem settings;
461	    settings.label  = _L("Filament settings…");
462	    settings.invoke = [slot, preset = current.filament.preset_name, shown = current.filament.alias.ToStdString()] {
463	        if (ShellController* shell = installed_shell())
464	            shell->open_filament_help(slot, preset, shown);
465	    };
466	    rows.push_back(std::move(settings));
467	
468	    // Adding a slot is offered on the one-slot menu, which then becomes the
469	    // slot list with the new slot open; a slot's own view does not offer it.
470	    if (!from_list) {
471	        HeaderMenuItem add;
472	        add.label      = _L("Add a slot");
473	        add.keeps_open = true;
474	        add.invoke     = [self] {
475	            if (!self->m_host.plater) return;
476	            const auto added = SetupCommands::add_filament_slot(*self->m_host.plater);
477	            if (self->m_host.changed) self->m_host.changed();
478	            show(self, View{added, true});
479	        };
480	        rows.push_back(std::move(add));
481	    }
482	    menu->replace_items(std::move(rows));
483	}
