485	wxWindow* FilamentMenu::build_colour_row(const Ptr& self, wxWindow* parent, View view)
486	{
487	    const std::size_t slot    = view.slot.value_or(0);
488	    const auto&       palette = self->m_theme.palette(self->m_dark);
489	    const auto        slots   = SetupCommands::filament_slots();
490	    const wxColour    current = slot < slots.size() ? wxColour(slots[slot].colour) : wxColour();
491	
492	    // The slot's own colour first, then the saved ones, each once. No names:
493	    // the app holds a colour as a value and nothing more.
494	    std::vector<wxColour> colours;
495	    if (current.IsOk()) colours.push_back(current);
496	    for (const wxColour& saved : SetupCommands::saved_colours())
497	        if (std::find(colours.begin(), colours.end(), saved) == colours.end())
498	            colours.push_back(saved);
499	    if (colours.size() > kColourCells - 1) colours.resize(kColourCells - 1);
500	
501	    std::vector<ColourRow::Cell> cells;
502	    for (const wxColour& colour : colours)
503	        cells.push_back({colour, colour == current, [self, view, colour] {
504	                             // Colour only: the plan does not change, so the
505	                             // visit records nothing for the thread.
506	                             if (self->m_host.plater)
507	                                 SetupCommands::set_filament_colour(*self->m_host.plater, view.slot.value_or(0), colour);
508	                             if (self->m_host.changed) self->m_host.changed();
509	                             show(self, view);
510	                         }});
511	    cells.push_back({wxColour(), false, [self, view] { pick_colour(self, view.slot.value_or(0), view); }});
512	
513	    // The keyboard's place is kept by value, so it stays on the same colour
514	    // when applying it moves that colour to the front of the row.
515	    return new ColourRow(parent, self->m_theme, palette, std::move(cells), self->m_colour_cursor,
516	                         [self](const std::string& key) { self->m_colour_cursor = key; });
517	}
518	
519	void FilamentMenu::pick_colour(const Ptr& self, std::size_t slot, View back)
520	{
521	    step_out(self, back, [self, slot] {
522	        const auto   slots = SetupCommands::filament_slots();
523	        wxColourData data;
524	        data.SetChooseFull(true);
525	        if (slot < slots.size()) data.SetColour(wxColour(slots[slot].colour));
526	        const auto saved = SetupCommands::saved_colours();
527	        for (std::size_t i = 0; i < saved.size() && i < 16; ++i)
528	            data.SetCustomColour(int(i), saved[i]);
529	        wxColourDialog dialog(self->m_owner, &data);
530	        dialog.CenterOnParent();
531	        if (dialog.ShowModal() == wxID_OK) {
532	            const wxColour picked = dialog.GetColourData().GetColour();
533	            SetupCommands::remember_colour(picked);
534	            if (self->m_host.plater) SetupCommands::set_filament_colour(*self->m_host.plater, slot, picked);
535	            if (self->m_host.changed) self->m_host.changed();
536	        }
537	    });
538	}
